def match(word):
    meaning = word.get("meaning","").strip()
    kanji = word.get("kanji","").strip()
    text = meaning + kanji
    for cat, kws in KW.items():
        for kw in kws:
            if kw and kw in text:
                return True, cat
    return False, None

def main():
    with open(VOCAB, "r", encoding="utf-8") as f:
        vocab = json.load(f)
    total = 0
    rows = []
    by_cat = {}
    by_lesson = {}
    for lid, lesson in vocab["lessons"].items():
        lc = 0; li = 0
        for w in lesson["words"]:
            total += 1; lc += 1
            ok, cat = match(w)
            if ok:
                rows.append({"lesson_id":lid,"word_id":w["id"],"kanji":w.get("kanji",""),
                    "hiragana":w.get("hiragana",""),"romaji":w.get("romaji",""),
                    "meaning":w.get("meaning",""),"category":cat})
                li += 1; by_cat[cat] = by_cat.get(cat,0)+1
        by_lesson[lid] = (lc, li)
    print(f"总词数: {total}")
    print(f"适合配图: {len(rows)} ({len(rows)/total*100:.1f}%)")
    print("\n按类别:")
    for c,n in sorted(by_cat.items(), key=lambda x:-x[1]):
        print(f"  {c}: {n}")
    print("\n按课程:")
    for lid,(tc,ic) in by_lesson.items():
        print(f"  {lid}: {ic}/{tc}")
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", encoding="utf-8-sig", newline="") as f:
        w = csv.DictWriter(f, fieldnames=["lesson_id","word_id","kanji","hiragana","romaji","meaning","category"])
        w.writeheader(); w.writerows(rows)
    print(f"\n保存到: {OUT}")

if __name__ == "__main__":
    main()
